// makeVoiceover generates one tiny audio-only MKA (lavfi sine → aac, the mka
// voiceover shape the serial scanner stamps as an audio sidecar). Returns the
// file's absolute path. No network, in-process.
func makeVoiceover(t *testing.T, dir, name string, freq int, dur time.Duration) string {
	t.Helper()
	requireFFmpeg(t)
	out := filepath.Join(dir, name)
	args := []string{
		"-nostdin", "-y",
		"-f", "lavfi", "-i", "sine=frequency=" + strconv.Itoa(freq) + ":sample_rate=44100:duration=" +
			strconv.FormatFloat(dur.Seconds(), 'f', 2, 64),
		"-c:a", "aac",
		out,
	}
	if b, err := exec.Command("ffmpeg", args...).CombinedOutput(); err != nil {
		t.Fatalf("voiceover fixture %s failed: %v: %s", name, err, truncate(b, 400))
	}
	return out
}

// mediaURIs extracts the URI attribute of every EXT-X-MEDIA tag, in playlist
// order — the master playlist's rendition declaration order.
func mediaURIs(master string) []string {
	var out []string
	for _, l := range strings.Split(master, "\n") {
		if !strings.HasPrefix(l, "#EXT-X-MEDIA") {
			continue
		}
		if i := strings.Index(l, `URI="`); i >= 0 {
			rest := l[i+len(`URI="`):]
			if j := strings.Index(rest, `"`); j >= 0 {
				out = append(out, rest[:j])
			}
		}
	}
	return out
}

// TestPackRenditions is the spec floor for the voiceover rendition pack lane
// (serial-watch-flow, probes 99170732b4589948 + c8cb3c70656c2c4b): a packaged
// episode with resolvable audio sidecars publishes the embedded audio plus the
// voiceovers as alternate audio renditions in document order (stream copy
// everywhere), and a sidecar missing at build time soft-omits while the rest
// publishes.
func TestPackRenditions(t *testing.T) {
	ctx := context.Background()

	t.Run("packaged_episode_carries_alternate_audio_renditions", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second) // head 5s + tail 7s: both phases run
		// Document order: the .mka dubs, distinct frequencies so a wrong order
		// is audible in the artifacts (and visible in the rendition indexes).
		v1 := makeVoiceover(t, dir, "rus1.mka", 600, 12*time.Second)
		v2 := makeVoiceover(t, dir, "rus2.mka", 800, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

		build, err := s.Pack(ctx, "it_rend", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}},
			[]string{v1, v2})
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "it_rend", build.Nonce)
		if build.Playlist != mediaPrefix+"/it_rend/"+build.Nonce+"/index.m3u8" {
			t.Fatalf("Build.Playlist = %q, want the build root's index.m3u8", build.Playlist)
		}

		// The master playlist declares the audio group: embedded audio first,
		// then the voiceovers in document order (the order hls.js exposes as
		// audio tracks — document index k → track k+1, 0 = embedded).
		master := readFile(t, filepath.Join(buildDir, "index.m3u8"))
		want := []string{"rend1/index.m3u8", "rend2/index.m3u8", "rend3/index.m3u8"}
		if got := mediaURIs(master); len(got) != len(want) {
			t.Fatalf("master EXT-X-MEDIA URIs = %v, want %v (embedded first, document order)",
				got, want)
		} else {
			for i := range want {
				if got[i] != want[i] {
					t.Fatalf("master EXT-X-MEDIA URI %d = %q, want %q", i, got[i], want[i])
				}
			}
		}
		if !strings.Contains(master, `TYPE=AUDIO`) || !strings.Contains(master, `AUDIO="group_aud"`) {
			t.Fatalf("master does not declare the audio group:\n%s", master)
		}
		// The master is static and never ends the build; ENDLIST belongs to
		// the variant playlists it references.
		if strings.Contains(master, "#EXT-X-ENDLIST") {
			t.Fatalf("master carries ENDLIST:\n%s", master)
		}

		// Both phases completed: every variant playlist is the grown,
		// ENDLIST-terminated merge with the tail spliced under t/.
		for _, k := range []string{"rend0", "rend1", "rend2", "rend3"} {
			pl := readFile(t, filepath.Join(buildDir, k, "index.m3u8"))
			if !strings.Contains(pl, "#EXT-X-ENDLIST") || !strings.Contains(pl, "#EXT-X-DISCONTINUITY") {
				t.Fatalf("%s playlist missing the completed merge markers:\n%s", k, pl)
			}
		}

		// Stream copy only, and the variant split is honest: variant 0 is the
		// video alone, the audio renditions are audio-only in declared order.
		video := streamKinds(probeStreams(t, filepath.Join(buildDir, "rend0", "init_0.mp4")))
		if video["video"] != 1 || video["audio"] != 0 {
			t.Fatalf("rend0 init streams = %v, want video only", video)
		}
		codec := func(init string) string {
			for _, st := range probeStreams(t, init) {
				if st["codec_type"] == "audio" {
					c, _ := st["codec_name"].(string)
					return c
				}
			}
			return ""
		}
		if got := codec(filepath.Join(buildDir, "rend1", "init_1.mp4")); got != "aac" {
			t.Fatalf("embedded rendition codec = %q, want the fixture's copied aac (no re-encode)", got)
		}
		if got := codec(filepath.Join(buildDir, "rend2", "init_2.mp4")); got != "aac" {
			t.Fatalf("voiceover rendition codec = %q, want the sidecar's copied aac", got)
		}
		if kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "rend2", "init_2.mp4"))); kinds["video"] != 0 || kinds["audio"] != 1 {
			t.Fatalf("rend2 init streams = %v, want audio only", kinds)
		}

		// The whole build probes as playable media (the master resolves).
		if kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "index.m3u8"))); kinds["video"] < 1 || kinds["audio"] < 1 {
			t.Fatalf("master probe streams = %v, want playable media", kinds)
		}
	})

	t.Run("unreadable_voiceover_soft_omits_and_rest_publishes", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		present := makeVoiceover(t, dir, "v1.mka", 600, 12*time.Second)
		missing := filepath.Join(dir, "vanished.mka") // never written
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

		build, err := s.Pack(ctx, "it_soft", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}},
			[]string{missing, present})
		if err != nil {
			t.Fatalf("Pack with one missing sidecar: %v (soft-omit must publish the rest)", err)
		}
		buildDir := filepath.Join(s.Root, "it_soft", build.Nonce)
		master := readFile(t, filepath.Join(buildDir, "index.m3u8"))
		// Only the present sidecar rode the build: embedded + one voiceover.
		want := []string{"rend1/index.m3u8", "rend2/index.m3u8"}
		if got := mediaURIs(master); len(got) != 2 || got[0] != want[0] || got[1] != want[1] {
			t.Fatalf("master EXT-X-MEDIA URIs = %v, want %v", got, want)
		}
		// The published build is playable media (the whole pack did not fail).
		if kinds := streamKinds(probeStreams(t, filepath.Join(buildDir, "index.m3u8"))); kinds["video"] < 1 || kinds["audio"] < 1 {
			t.Fatalf("master probe streams = %v, want playable media", kinds)
		}
	})

	t.Run("no_resolvable_voiceover_keeps_legacy_single_variant_build", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 12*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 600*time.Second)

		build, err := s.Pack(ctx, "it_legacy", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}},
			[]string{filepath.Join(dir, "gone.mka")}) // all soft-omitted
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "it_legacy", build.Nonce)
		pl := readFile(t, filepath.Join(buildDir, "index.m3u8"))
		if strings.Contains(pl, "#EXT-X-MEDIA:") {
			t.Fatalf("all-omitted build declared renditions:\n%s", pl)
		}
		if _, err := os.Stat(filepath.Join(buildDir, "rend0")); err == nil {
			t.Fatal("all-omitted build published rendition directories")
		}
	})

	t.Run("rendition_arg_builders_carry_the_locked_flags", func(t *testing.T) {
		voiceovers := []string{"/lib/Rus sound/ep01.mka", "/lib/Rus sound/ep01.2.mka"}
		cases := []struct {
			name    string
			args    []string
			seekTo  bool
			limitTo bool
		}{
			{"head", renditionArgs("/in/f.mkv", voiceovers, 600*time.Second, 4*time.Second, "/out", false), false, true},
			{"tail", renditionArgs("/in/f.mkv", voiceovers, 600*time.Second, 4*time.Second, "/out", true), true, false},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				joined := strings.Join(tc.args, "\x00")
				for _, want := range []string{
					"-nostdin",
					"-map\x000:v:0", "-map\x000:a:0",
					"-map\x001:a:0", "-map\x002:a:0",
					"-var_stream_map\x00v:0,agroup:aud a:0,agroup:aud a:1,agroup:aud a:2,agroup:aud",
					"-sn\x00-dn", "-c\x00copy", "-f\x00hls",
					"-hls_segment_type\x00fmp4",
					"-master_pl_name\x00index.m3u8",
				} {
					if !strings.Contains(joined, want) {
						t.Fatalf("args missing %q: %q", want, joined)
					}
				}
				if tc.seekTo {
					// Every input is seeked in the tail phase — a voiceover
					// that re-read from its start would duplicate its audio.
					for _, want := range []string{
						"-ss\x00600.000\x00-i\x00/in/f.mkv",
						"-ss\x00600.000\x00-i\x00/lib/Rus sound/ep01.mka",
						"-ss\x00600.000\x00-i\x00/lib/Rus sound/ep01.2.mka",
					} {
						if !strings.Contains(joined, want) {
							t.Fatalf("tail args missing %q: %q", want, joined)
						}
					}
				}
				for _, banned := range []string{"libx264", "-c:v", "-vf", "aac", "sh"} {
					if strings.Contains(joined, banned) {
						t.Fatalf("args carry encoder/transform flag %q (remux only): %q", banned, joined)
					}
				}
				if tc.seekTo && strings.Contains(joined, "omit_endlist") {
					t.Fatal("tail args must not omit ENDLIST")
				}
				if tc.limitTo {
					if !strings.Contains(joined, "-t\x00600.000") || !strings.Contains(joined, "omit_endlist") {
						t.Fatalf("head args missing the -t cap / EVENT ENDLIST omission: %q", joined)
					}
				}
			})
		}
	})
}

// TestVoiceoverTracks is the spec floor for the playback descriptor's read-only
// voiceovers projection (serial-watch-flow, probe 61ba379799f368ce): document-
// order {index, label} entries over the episode document's audio sidecars,
// label = language else containing folder else file name, an empty list when
// none, and no packaging-state mutation.
func TestVoiceoverTracks(t *testing.T) {
	s := &Service{Secret: []byte("k")}

	t.Run("descriptor_lists_voiceovers_from_stored_facts", func(t *testing.T) {
		d := map[string]any{"parsed": map[string]any{
			"sidecars": []any{
				map[string]any{"relative_path": "Rus subs/ep01.srt", "kind": "subtitle", "language": "rus"},
				map[string]any{"relative_path": "Rus sound/ep01.mka", "kind": "audio", "language": "rus"},
				map[string]any{"relative_path": "Rus sound/ep01.2.mka", "kind": "audio"},
				map[string]any{"relative_path": "theme.flac", "kind": "audio"}, // no folder, no language
			},
		}}
		_, _, _, _, voiceovers := s.Describe("it", d)
		if len(voiceovers) != 3 {
			t.Fatalf("voiceovers = %v, want 3 audio entries (subtitles never project)", voiceovers)
		}
		type vo struct {
			index int
			label string
		}
		want := []vo{{1, "rus"}, {2, "Rus sound"}, {3, "theme.flac"}}
		for i, w := range want {
			idx, _ := voiceovers[i]["index"].(int)
			label, _ := voiceovers[i]["label"].(string)
			if idx != w.index || label != w.label {
				t.Fatalf("voiceover %d = {%v %v}, want {%d %q} (document index; language else folder else file)",
					i, idx, label, w.index, w.label)
			}
		}
	})

	t.Run("empty_list_when_no_sidecars", func(t *testing.T) {
		for name, d := range map[string]map[string]any{
			"no_parsed":  {},
			"no_sidecar": {"parsed": map[string]any{"absolute_path": "/lib/f.mkv"}},
			"empty":      {"parsed": map[string]any{"sidecars": []any{}}},
		} {
			_, _, _, _, voiceovers := s.Describe("it", d)
			if voiceovers == nil || len(voiceovers) != 0 {
				t.Fatalf("%s: voiceovers = %#v, want an empty list", name, voiceovers)
			}
		}
	})

	t.Run("read_only_no_packaging_state_mutation", func(t *testing.T) {
		d := map[string]any{
			"streams": map[string]any{"state": "complete", "playlist": "/media/it/n0/index.m3u8", "nonce": "n0"},
			"parsed": map[string]any{"sidecars": []any{
				map[string]any{"relative_path": "Rus sound/ep01.mka", "kind": "audio", "language": "rus"},
			}},
		}
		before, err := json.Marshal(d)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		mode1, state1, url1, _, vo1 := s.Describe("it", d)
		mode2, state2, url2, _, vo2 := s.Describe("it", d)
		after, err := json.Marshal(d)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		if string(before) != string(after) {
			t.Fatalf("Describe mutated the document:\nbefore %s\nafter  %s", before, after)
		}
		if mode1 != ModeHls || mode2 != mode1 || state1 != StateComplete || state2 != state1 || url1 != url2 {
			t.Fatalf("packaging state changed between reads: %q/%q %q/%q %q/%q",
				mode1, mode2, state1, state2, url1, url2)
		}
		if len(vo1) != 1 || len(vo2) != 1 {
			t.Fatalf("voiceovers = %v / %v, want one entry on both reads", vo1, vo2)
		}
	})
}
